// Description: C header of the spi_flash_ctrl register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-16
#ifndef SPI_FLASH_CTRL_REGS_H
#define SPI_FLASH_CTRL_REGS_H
#define SPI_FLASH_CTRL_REGS_ID_OFFSET 0x00u
#define SPI_FLASH_CTRL_REGS_VERSION_OFFSET 0x04u
#define SPI_FLASH_CTRL_REGS_DATE_OFFSET 0x08u
#define SPI_FLASH_CTRL_REGS_ID_VALUE 0x5350464Cu   /* "SPFL" */
#define SPI_FLASH_CTRL_REGS_CMD_OFFSET 0x10u   /* RW */
#define SPI_FLASH_CTRL_REGS_CMD_RESET 0x00000000u
#define SPI_FLASH_CTRL_REGS_CMD_OPCODE_SHIFT 0u
#define SPI_FLASH_CTRL_REGS_CMD_OPCODE_MASK 0x000000FFu
#define SPI_FLASH_CTRL_REGS_CMD_ADDR_EN_SHIFT 8u
#define SPI_FLASH_CTRL_REGS_CMD_ADDR_EN_MASK 0x00000100u
#define SPI_FLASH_CTRL_REGS_CMD_DUMMY_SHIFT 12u
#define SPI_FLASH_CTRL_REGS_CMD_DUMMY_MASK 0x0000F000u
#define SPI_FLASH_CTRL_REGS_CMD_READ_DATA_SHIFT 16u
#define SPI_FLASH_CTRL_REGS_CMD_READ_DATA_MASK 0x00010000u
#define SPI_FLASH_CTRL_REGS_CMD_WRITE_DATA_SHIFT 17u
#define SPI_FLASH_CTRL_REGS_CMD_WRITE_DATA_MASK 0x00020000u
#define SPI_FLASH_CTRL_REGS_ADDR_OFFSET 0x14u   /* RW */
#define SPI_FLASH_CTRL_REGS_ADDR_RESET 0x00000000u
#define SPI_FLASH_CTRL_REGS_LEN_OFFSET 0x18u   /* RW */
#define SPI_FLASH_CTRL_REGS_LEN_RESET 0x00000000u
#define SPI_FLASH_CTRL_REGS_CLKDIV_OFFSET 0x1Cu   /* RW */
#define SPI_FLASH_CTRL_REGS_CLKDIV_RESET 0x00000004u
#define SPI_FLASH_CTRL_REGS_STATUS_OFFSET 0x20u   /* CMD */
#define SPI_FLASH_CTRL_REGS_STATUS_RESET 0x00000000u
#define SPI_FLASH_CTRL_REGS_STATUS_BUSY_SHIFT 0u
#define SPI_FLASH_CTRL_REGS_STATUS_BUSY_MASK 0x00000001u
#define SPI_FLASH_CTRL_REGS_STATUS_DONE_SHIFT 1u
#define SPI_FLASH_CTRL_REGS_STATUS_DONE_MASK 0x00000002u
#define SPI_FLASH_CTRL_REGS_STATUS_CMD_ERR_SHIFT 2u
#define SPI_FLASH_CTRL_REGS_STATUS_CMD_ERR_MASK 0x00000004u
#define SPI_FLASH_CTRL_REGS_IRQ_EN_OFFSET 0x24u   /* RW */
#define SPI_FLASH_CTRL_REGS_IRQ_EN_RESET 0x00000000u
#endif /* SPI_FLASH_CTRL_REGS_H */
